async function run() {
  const results = {};

  // #3 get_function_details 静默丢弃未知名
  try {
    const fnDetails = await get_function_details(["Bogus.nonexistent", "Developer.shell"]);
    const keys = Object.keys(fnDetails);
    results.gfd_keys = keys;
    results.gfd_bogus_exists = keys.includes("Bogus.nonexistent") || keys.some(k => k.includes("Bogus"));
    results.gfd_shell_exists = keys.includes("Developer.shell");
  } catch(e) {
    results.gfd_error = e.message;
  }

  // #5 import/fs 报错口径
  try {
    const fsMod = await import("fs");
    results.fs_import = "resolved: " + typeof fsMod;
  } catch(e) {
    results.fs_import = "ERROR: " + String(e.message).slice(0, 120);
  }
  results.fetch_type = typeof fetch;
  results.require_type = typeof (globalThis as any).require;
  results.process_exists = typeof process;
  results.deno_exists = typeof Deno;

  // #7 read binary 乱码
  // write a fake pdf
  try {
    await write({
      path: "/Users/billtse/.agnes/temporary/2026-10-12/20261012_24/work/fake.pdf",
      content: "%PDF-1.4 fake binary test"
    });
    const readResult = await read({
      path: "/Users/billtse/.agnes/temporary/2026-10-12/20261012_24/work/fake.pdf",
      limit: 5
    });
    results.read_fake_pdf = String(readResult).slice(0, 100);
    results.read_fake_pdf_error = false;
  } catch(e) {
    results.read_fake_pdf_error = true;
    results.read_fake_pdf_msg = String(e.message).slice(0, 150);
  }

  return results;
}

