async function run() {
  const results: Record<string, any> = {};

  // #3 get_function_details: 传一个假名 + 一个真名，看假名是否被静默丢弃
  try {
    const fnDetails = await get_function_details(["Bogus.nonexistent", "Developer.shell"]);
    const keys: string[] = Object.keys(fnDetails);
    results.gfd_keys_count = keys.length;
    results.gfd_bogus_in_keys = keys.some((k: string) => k.includes("Bogus"));
    results.gfd_shell_in_keys = keys.includes("Developer.shell");
    results.gfd_any_notfound_msg = JSON.stringify(fnDetails).includes("not found") || JSON.stringify(fnDetails).includes("notFound");
  } catch (e) {
    results.gfd_error = String(e).slice(0, 200);
  }

  // #5 import/fs / fetch / require / process / Deno 口径
  // fs: 不用 import()，用 globalThis 检测
  results.fs_on_globalThis = typeof (globalThis as any).fs;
  results.fetch_type = typeof (globalThis as any).fetch;
  results.require_type = typeof (globalThis as any).require;
  results.process_type = typeof (globalThis as any).process;
  results.deno_type = typeof (globalThis as any).Deno;

  // #7 read 一个含 %PDF 前缀的文本文件，看是否静默返回文本
  try {
    await write({
      path: "/Users/billtse/.agnes/temporary/2026-10-12/20261012_24/work/fake.pdf",
      content: "%PDF-1.4 fake binary test\nhello"
    });
    const readResult = await read({
      path: "/Users/billtse/.agnes/temporary/2026-10-12/20261012_24/work/fake.pdf",
      limit: 5
    });
    results.read_fake_pdf_text = String(readResult).slice(0, 120);
    results.read_fake_pdf_rejected = false;
  } catch (e) {
    results.read_fake_pdf_rejected = true;
    results.read_fake_pdf_msg = String(e).slice(0, 200);
  }

  return results;
}

